<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Notification Preferences</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f5f7fb;
        --surface: rgba(255, 255, 255, 0.92);
        --surface-border: rgba(15, 23, 42, 0.08);
        --text: #0f172a;
        --muted: #64748b;
        --accent: #4f46e5;
        --accent-soft: rgba(79, 70, 229, 0.12);
        --shadow: 0 24px 60px rgba(15, 23, 42, 0.12);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, rgba(79, 70, 229, 0.14), transparent 34%),
          linear-gradient(180deg, #eef2ff 0%, var(--bg) 42%, #ffffff 100%);
        display: grid;
        place-items: center;
        padding: 24px;
      }

      .page-shell {
        width: min(100%, 680px);
      }

      .card {
        background: var(--surface);
        border: 1px solid var(--surface-border);
        border-radius: 24px;
        box-shadow: var(--shadow);
        overflow: hidden;
        backdrop-filter: blur(18px);
      }

      .card-header {
        padding: 32px 32px 0;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        padding: 8px 12px;
        border-radius: 999px;
        background: var(--accent-soft);
        color: var(--accent);
        font-size: 0.875rem;
        font-weight: 600;
      }

      h1 {
        margin: 16px 0 8px;
        font-size: clamp(1.8rem, 3vw, 2.4rem);
        line-height: 1.15;
        letter-spacing: -0.03em;
      }

      .subtitle {
        margin: 0;
        color: var(--muted);
        font-size: 1rem;
        line-height: 1.6;
      }

      form {
        padding: 28px 32px 32px;
      }

      .form-field {
        padding: 24px;
        border-radius: 20px;
        border: 1px solid rgba(79, 70, 229, 0.12);
        background: linear-gradient(180deg, rgba(255, 255, 255, 0.95), rgba(248, 250, 252, 0.96));
      }

      fieldset {
        margin: 0;
        padding: 0;
        border: 0;
      }

      legend {
        padding: 0;
        margin-bottom: 16px;
        font-size: 1.05rem;
        font-weight: 700;
      }

      .choices {
        display: grid;
        gap: 12px;
      }

      .choice {
        position: relative;
      }

      .choice input {
        position: absolute;
        opacity: 0;
        pointer-events: none;
      }

      .choice label {
        display: flex;
        align-items: center;
        gap: 14px;
        width: 100%;
        padding: 16px 18px;
        border-radius: 16px;
        border: 1px solid rgba(100, 116, 139, 0.18);
        background: #fff;
        cursor: pointer;
        transition: transform 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
      }

      .choice label:hover {
        transform: translateY(-1px);
        border-color: rgba(79, 70, 229, 0.34);
        box-shadow: 0 10px 24px rgba(15, 23, 42, 0.08);
      }

      .choice input:focus-visible + label {
        outline: 3px solid rgba(79, 70, 229, 0.28);
        outline-offset: 2px;
      }

      .choice input:checked + label {
        border-color: rgba(79, 70, 229, 0.6);
        background: linear-gradient(180deg, rgba(79, 70, 229, 0.08), rgba(255, 255, 255, 1));
        box-shadow: 0 12px 28px rgba(79, 70, 229, 0.12);
      }

      .radio-mark {
        width: 20px;
        height: 20px;
        border-radius: 50%;
        border: 2px solid #94a3b8;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        flex: 0 0 auto;
      }

      .choice input:checked + label .radio-mark {
        border-color: var(--accent);
      }

      .choice input:checked + label .radio-mark::after {
        content: "";
        width: 10px;
        height: 10px;
        border-radius: 50%;
        background: var(--accent);
      }

      .choice-text {
        font-size: 1rem;
        font-weight: 600;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
        margin-top: 24px;
      }

      button {
        appearance: none;
        border: 0;
        border-radius: 14px;
        padding: 14px 20px;
        background: linear-gradient(135deg, #4f46e5, #6366f1);
        color: #fff;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        box-shadow: 0 14px 30px rgba(79, 70, 229, 0.3);
        transition: transform 0.18s ease, box-shadow 0.18s ease;
      }

      button:hover {
        transform: translateY(-1px);
        box-shadow: 0 18px 36px rgba(79, 70, 229, 0.34);
      }

      button:focus-visible {
        outline: 3px solid rgba(79, 70, 229, 0.32);
        outline-offset: 3px;
      }

      @media (max-width: 640px) {
        .card-header,
        form {
          padding-left: 20px;
          padding-right: 20px;
        }

        .form-field {
          padding: 18px;
        }

        .actions {
          justify-content: stretch;
        }

        button {
          width: 100%;
        }
      }
    </style>
  </head>
  <body>
    <main class="page-shell" id="app" aria-live="polite"></main>

    <script>
      const notificationChoices = [
        { value: "email", label: "Email" },
        { value: "sms", label: "SMS" },
        { value: "push", label: "Push Notifications" },
      ];

      function RadioChoice({ value, label, checked = false }) {
        return `
          <div class="choice">
            <input type="radio" id="${value}" name="notification-preference" value="${value}" ${checked ? "checked" : ""} required />
            <label for="${value}">
              <span class="radio-mark" aria-hidden="true"></span>
              <span class="choice-text">${label}</span>
            </label>
          </div>
        `;
      }

      function NotificationForm() {
        return `
          <section class="card" aria-labelledby="form-title">
            <header class="card-header">
              <span class="eyebrow">Preferences</span>
              <h1 id="form-title">Choose your notification channel</h1>
              <p class="subtitle">Select one option for how you'd like to stay updated.</p>
            </header>

            <form>
              <div class="form-field">
                <fieldset>
                  <legend>How do you prefer to receive notifications?</legend>
                  <div class="choices" role="radiogroup" aria-label="How do you prefer to receive notifications?">
                    ${notificationChoices
                      .map((choice, index) => RadioChoice({ ...choice, checked: index === 0 }))
                      .join("")}
                  </div>
                </fieldset>
              </div>

              <div class="actions">
                <button type="submit">Submit</button>
              </div>
            </form>
          </section>
        `;
      }

      document.getElementById("app").innerHTML = NotificationForm();
    </script>
  </body>
</html>
